341	            assertEquals(root, node.path("unavailableDueToRecalledAncestor").asText());
342	        }
343	        // 祖先查询：grandChild 的祖先 child 被根召回阻断，root 自身是直接召回不算祖先召回
344	        MvcResult ancestors = mockMvc.perform(get("/api/batches/" + grandChild + "/ancestors"))
