package com.example.starter.batch;

import com.example.starter.batch.dto.BindCertificatesRequest;
import com.example.starter.batch.dto.BindCertificatesResponse;
import com.example.starter.batch.dto.BindingResponse;
import com.example.starter.batch.dto.DeclarationRef;
import com.example.starter.batch.dto.DeclarationVersionResponse;
import com.example.starter.batch.dto.MergeBatchesRequest;
import com.example.starter.batch.dto.MergeResponse;
import com.example.starter.batch.dto.PublishDeclarationRequest;
import com.example.starter.batch.dto.ReleaseCheckResponse;
import com.example.starter.batch.dto.WithdrawDeclarationRequest;
import com.example.starter.batch.dto.WithdrawDeclarationResponse;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * 批次合格证匹配与供应商声明版本门禁核心服务。
 *
 * <p>声明按 declarationKey 版本化发布；同物料下前缀重叠（互为前缀）的 ACTIVE 声明
 * 不得优先级相同（422）；有效区间左闭右开，非法区间 422。批次放行前必须绑定与物料、
 * 批号前缀匹配且在放行时点有效的声明版本；批量绑定任一失效整次回滚。
 * 发布/撤回通过 declaration_lock 单行锁串行化，按事务提交顺序裁决；
 * commandKey 幂等由 {@link IdempotentExecutor} 保证，失败不占键。
 */
@Service
public class CertificateService {

    private static final String CMD_PUBLISH = "PUBLISH_DECLARATION";
    private static final String CMD_WITHDRAW = "WITHDRAW_DECLARATION";
    private static final String CMD_BIND = "BIND_CERTIFICATE";
    private static final String CMD_MERGE = "MERGE_BATCH";

    private final BatchRepository batchRepo;
    private final CertificateRepository certRepo;
    private final IdempotentExecutor idempotent;
    private final ObjectMapper objectMapper;
    private final Clock clock;

    public CertificateService(BatchRepository batchRepo,
                              CertificateRepository certRepo,
                              IdempotentExecutor idempotent,
                              ObjectMapper objectMapper,
                              Clock clock) {
        this.batchRepo = batchRepo;
        this.certRepo = certRepo;
        this.idempotent = idempotent;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    /**
     * 发布声明新版本：版本号在 declarationKey 内自增；有效区间非法或
     * 同物料前缀重叠且优先级相同返回 422。
     */
    public StoredResponse publish(String actorId, PublishDeclarationRequest req) {
        String actor = requireActor(actorId);
        if (!req.validFrom().isBefore(req.validTo())) {
            throw ApiException.unprocessable(
                    "有效区间非法：validFrom 必须早于 validTo（左闭右开），实际 validFrom="
                            + req.validFrom() + " validTo=" + req.validTo());
        }
        String fingerprint = Fingerprints.of("publish", actor, req.declarationKey(),
                req.materialCode(), req.batchNoPrefix(), req.priority().toString(),
                req.validFrom().toString(), req.validTo().toString());
        return idempotent.execute(CMD_PUBLISH, req.commandKey(), fingerprint, () -> {
            certRepo.lockDeclarations();
            // 持锁后重查命令快照：并发同键请求在锁等待期间可能已由对方提交
            var logged = idempotent.logged(CMD_PUBLISH, req.commandKey(), fingerprint);
            if (logged.isPresent()) {
                return logged.get();
            }
            for (CertificateRepository.DeclarationRow other
                    : certRepo.findActiveByMaterial(req.materialCode())) {
                if (other.declarationKey().equals(req.declarationKey())) {
                    continue;
                }
                if (other.priority() == req.priority()
                        && prefixesOverlap(other.batchNoPrefix(), req.batchNoPrefix())) {
                    throw ApiException.unprocessable("声明前缀重叠且优先级相同: "
                            + other.declarationKey() + "#" + other.version()
                            + " 前缀=" + other.batchNoPrefix() + " 与 " + req.batchNoPrefix());
                }
            }
            int version = certRepo.findVersions(req.declarationKey()).stream()
                    .mapToInt(CertificateRepository.DeclarationRow::version).max().orElse(0) + 1;
            String now = now();
            CertificateRepository.DeclarationRow row = new CertificateRepository.DeclarationRow(
                    0L, req.declarationKey(), version, req.materialCode(), req.batchNoPrefix(),
                    req.priority(), req.validFrom().toString(), req.validTo().toString(),
                    DeclarationStatus.ACTIVE.name(), actor, now, null);
            certRepo.insertDeclaration(row);
            return new StoredResponse(201, toJson(toDeclarationResponse(row)));
        });
    }

    /**
     * 撤回声明：全部 ACTIVE 版本置为 WITHDRAWN，只影响后续绑定与放行，不改写历史快照。
     */
    public StoredResponse withdraw(String declarationKey, String actorId,
                                   WithdrawDeclarationRequest req) {
        String actor = requireActor(actorId);
        String fingerprint = Fingerprints.of("withdraw", actor, declarationKey);
        return idempotent.execute(CMD_WITHDRAW, req.commandKey(), fingerprint, () -> {
            certRepo.lockDeclarations();
            var logged = idempotent.logged(CMD_WITHDRAW, req.commandKey(), fingerprint);
            if (logged.isPresent()) {
                return logged.get();
            }
            List<CertificateRepository.DeclarationRow> versions =
                    certRepo.findVersionsForUpdate(declarationKey);
            if (versions.isEmpty()) {
                throw ApiException.notFound("声明不存在: " + declarationKey);
            }
            boolean anyActive = versions.stream()
                    .anyMatch(v -> DeclarationStatus.ACTIVE.name().equals(v.status()));
            if (!anyActive) {
                throw ApiException.conflict("声明已撤回: " + declarationKey);
            }
            String now = now();
            int count = certRepo.withdraw(declarationKey, now);
            WithdrawDeclarationResponse body = new WithdrawDeclarationResponse(declarationKey,
                    count, DeclarationStatus.WITHDRAWN, Instant.parse(now));
            return new StoredResponse(201, toJson(body));
        });
    }

    /**
     * 批量绑定声明版本：先完整校验全部绑定（存在、ACTIVE、在有效期、物料与批号前缀匹配、
     * 未重复绑定），任一失效整次回滚；全部通过后在一个事务中写入。
     */
    public StoredResponse bind(String batchKey, String actorId, BindCertificatesRequest req) {
        String actor = requireActor(actorId);
        List<DeclarationRef> refs = req.bindings();
        Set<String> seen = new HashSet<>();
        for (DeclarationRef ref : refs) {
            if (!seen.add(ref.declarationKey() + "�" + ref.version())) {
                throw ApiException.conflict("请求内声明引用重复: "
                        + ref.declarationKey() + "#" + ref.version());
            }
        }
        List<String> fpParts = new ArrayList<>(List.of("bind", actor, batchKey));
        refs.stream()
                .sorted(Comparator.comparing(DeclarationRef::declarationKey)
                        .thenComparingInt(DeclarationRef::version))
                .forEach(ref -> {
                    fpParts.add(ref.declarationKey());
                    fpParts.add(ref.version().toString());
                });
        String fingerprint = Fingerprints.of(fpParts.toArray(new String[0]));
        return idempotent.execute(CMD_BIND, req.commandKey(), fingerprint, () -> {
            BatchRepository.BatchRow batch = batchRepo.findBatchForUpdate(batchKey)
                    .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
            var logged = idempotent.logged(CMD_BIND, req.commandKey(), fingerprint);
            if (logged.isPresent()) {
                return logged.get();
            }
            BatchStatus status = BatchStatus.valueOf(batch.status());
            if (status != BatchStatus.QUARANTINED && status != BatchStatus.PENDING_RELEASE
                    && status != BatchStatus.RELEASE_REVIEW) {
                throw ApiException.conflict("批次状态 " + status + " 不允许绑定合格证声明");
            }
            Instant nowInstant = clock.instant();
            List<CertificateRepository.DeclarationRow> declarations = new ArrayList<>(refs.size());
            for (DeclarationRef ref : refs) {
                CertificateRepository.DeclarationRow d = certRepo
                        .findDeclaration(ref.declarationKey(), ref.version())
                        .orElseThrow(() -> ApiException.notFound("声明版本不存在: "
                                + ref.declarationKey() + "#" + ref.version()));
                if (!DeclarationStatus.ACTIVE.name().equals(d.status())) {
                    throw ApiException.unprocessable("声明已撤回，不可绑定: "
                            + ref.declarationKey() + "#" + ref.version());
                }
                if (!d.materialCode().equals(batch.productCode())) {
                    throw ApiException.unprocessable("批次物料与声明物料不匹配: 批次物料="
                            + batch.productCode() + " 声明物料=" + d.materialCode());
                }
                if (!batch.batchNo().startsWith(d.batchNoPrefix())) {
                    throw ApiException.unprocessable("批号不匹配声明允许前缀: 批号="
                            + batch.batchNo() + " 前缀=" + d.batchNoPrefix());
                }
                if (!withinValidity(d, nowInstant)) {
                    throw ApiException.unprocessable("声明不在有效期（左闭右开）: "
                            + ref.declarationKey() + "#" + ref.version()
                            + " 区间=[" + d.validFrom() + ", " + d.validTo() + ") 当前=" + nowInstant);
                }
                if (certRepo.findBinding(batchKey, ref.declarationKey(), ref.version()).isPresent()) {
                    throw ApiException.conflict("声明已绑定: "
                            + ref.declarationKey() + "#" + ref.version());
                }
                declarations.add(d);
            }
            String now = now();
            List<BindingResponse> bodies = new ArrayList<>(declarations.size());
            for (CertificateRepository.DeclarationRow d : declarations) {
                certRepo.insertBinding(new CertificateRepository.BindingRow(0L, batchKey,
                        d.declarationKey(), d.version(), d.materialCode(), d.batchNoPrefix(),
                        actor, now));
                bodies.add(new BindingResponse(batchKey, d.declarationKey(), d.version(),
                        d.materialCode(), d.batchNoPrefix(), actor, Instant.parse(now)));
            }
            return new StoredResponse(201, toJson(new BindCertificatesResponse(batchKey,
                    refs.size(), bodies.size(), bodies)));
        });
    }

    // ====MERGE_AND_QUERIES====

    /**
     * 两个批次号前缀是否重叠：任一前缀是另一个的前缀（空串与一切前缀重叠）。
     */
    static boolean prefixesOverlap(String a, String b) {
        return a.startsWith(b) || b.startsWith(a);
    }

    /**
     * 声明在给定时点是否处于有效区间：左闭右开 [validFrom, validTo)。
     */
    static boolean withinValidity(CertificateRepository.DeclarationRow d, Instant at) {
        return !at.isBefore(Instant.parse(d.validFrom())) && at.isBefore(Instant.parse(d.validTo()));
    }

    private String requireActor(String actorId) {
        if (actorId == null || actorId.isBlank()) {
            throw ApiException.badRequest("X-Actor-Id 不能为空");
        }
        return actorId.trim();
    }

    private DeclarationVersionResponse toDeclarationResponse(
            CertificateRepository.DeclarationRow row) {
        return new DeclarationVersionResponse(row.declarationKey(), row.version(),
                row.materialCode(), row.batchNoPrefix(), row.priority(),
                Instant.parse(row.validFrom()), Instant.parse(row.validTo()),
                DeclarationStatus.valueOf(row.status()), row.operator(),
                Instant.parse(row.createdAt()),
                row.withdrawnAt() == null ? null : Instant.parse(row.withdrawnAt()));
    }

    private BindingResponse toBindingResponse(CertificateRepository.BindingRow row) {
        return new BindingResponse(row.batchKey(), row.declarationKey(), row.declarationVersion(),
                row.materialCode(), row.batchNoPrefix(), row.boundBy(),
                Instant.parse(row.createdAt()));
    }

    private String toJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("响应序列化失败", e);
        }
    }

    private String now() {
        return clock.instant().toString();
    }
}

