/**
 * 合批：2～5 个当前可用的 RELEASED 父批合并为一个全新子批（初始 QUARANTINED，
 * producedAt 取合批时点）。必须提供覆盖全部父批物料的有效声明绑定（按子批批号
 * 前缀匹配且在合批时点有效），任一父物料未覆盖整次 422 回滚；
 * 先校验完整最终状态，再在一个事务中提交全部写入，父批全部置为 MERGED。
 */
public StoredResponse merge(String actorId, MergeBatchesRequest req) {
    String actor = requireActor(actorId);
    List<String> parentKeys = req.parentKeys();
    if (new HashSet<>(parentKeys).size() != parentKeys.size()) {
        throw ApiException.conflict("parentKeys 在请求内重复");
    }
    List<String> items = req.requiredTests().stream().map(String::trim).toList();
    if (new HashSet<>(items).size() != items.size()) {
        throw ApiException.badRequest("requiredTests 存在重复检验项");
    }
    Set<String> seenRefs = new HashSet<>();
    for (DeclarationRef ref : req.bindings()) {
        if (!seenRefs.add(ref.declarationKey() + " " + ref.version())) {
            throw ApiException.conflict("请求内声明引用重复: "
                    + ref.declarationKey() + "#" + ref.version());
        }
    }
    List<String> fpParts = new ArrayList<>(List.of("merge", actor, req.childBatchKey(),
            req.childBatchNo(), req.productCode()));
    fpParts.addAll(items);
    parentKeys.stream().sorted().forEach(fpParts::add);
    req.bindings().stream()
            .sorted(Comparator.comparing(DeclarationRef::declarationKey)
                    .thenComparingInt(DeclarationRef::version))
            .forEach(ref -> {
                fpParts.add(ref.declarationKey());
                fpParts.add(ref.version().toString());
            });
    String fingerprint = Fingerprints.of(fpParts.toArray(new String[0]));
    return idempotent.execute(CMD_MERGE, req.commandKey(), fingerprint, () -> {
        if (batchRepo.findBatch(req.childBatchKey()).isPresent()) {
            throw ApiException.conflict("childBatchKey 已存在: " + req.childBatchKey());
        }
        // 按业务键排序逐行锁定全部父批，保证与父批上其他事务的锁顺序确定
        List<String> sortedKeys = new ArrayList<>(parentKeys);
        Collections.sort(sortedKeys);
        Map<String, BatchRepository.BatchRow> parents = new HashMap<>();
        for (String key : sortedKeys) {
            BatchRepository.BatchRow row = batchRepo.findBatchForUpdate(key)
                    .orElseThrow(() -> ApiException.notFound("父批不存在: " + key));
            parents.put(key, row);
        }
        var logged = idempotent.logged(CMD_MERGE, req.commandKey(), fingerprint);
        if (logged.isPresent()) {
            return logged.get();
        }
        for (String key : sortedKeys) {
            assertNoRecalledAncestor(key);
            String parentStatus = parents.get(key).status();
            if (!BatchStatus.RELEASED.name().equals(parentStatus)) {
                throw ApiException.conflict(
                        "父批状态 " + parentStatus + " 不允许合批，仅 RELEASED 批次可合批: " + key);
            }
        }
        Instant nowInstant = clock.instant();
        Set<String> parentMaterials = new LinkedHashSet<>();
        for (String key : parentKeys) {
            parentMaterials.add(parents.get(key).productCode());
        }
        List<CertificateRepository.DeclarationRow> declarations =
                new ArrayList<>(req.bindings().size());
        for (DeclarationRef ref : req.bindings()) {
            CertificateRepository.DeclarationRow d = certRepo
                    .findDeclaration(ref.declarationKey(), ref.version())
                    .orElseThrow(() -> ApiException.notFound("声明版本不存在: "
                            + ref.declarationKey() + "#" + ref.version()));
            if (!DeclarationStatus.ACTIVE.name().equals(d.status())) {
                throw ApiException.unprocessable("声明已撤回，不可用于合批: "
                        + ref.declarationKey() + "#" + ref.version());
            }
            if (!withinValidity(d, nowInstant)) {
                throw ApiException.unprocessable("声明不在有效期（左闭右开）: "
                        + ref.declarationKey() + "#" + ref.version());
            }
            if (!parentMaterials.contains(d.materialCode())) {
                throw ApiException.unprocessable("声明物料与所有父批物料均不匹配: 声明物料="
                        + d.materialCode() + " 父批物料=" + parentMaterials);
            }
            if (!req.childBatchNo().startsWith(d.batchNoPrefix())) {
                throw ApiException.unprocessable("子批批号不匹配声明允许前缀: 批号="
                        + req.childBatchNo() + " 前缀=" + d.batchNoPrefix());
            }
            declarations.add(d);
        }
        Set<String> covered = new HashSet<>();
        for (CertificateRepository.DeclarationRow d : declarations) {
            covered.add(d.materialCode());
        }
        List<String> missing = parentMaterials.stream()
                .filter(m -> !covered.contains(m)).toList();
        if (!missing.isEmpty()) {
            throw ApiException.unprocessable("父物料缺少有效合格证声明: 要求覆盖 "
                    + parentMaterials.size() + " 种，实际覆盖 " + covered.size()
                    + " 种，缺失 " + missing);
        }
        String now = now();
        batchRepo.insertBatch(new BatchRepository.BatchRow(0L, req.childBatchKey(),
                req.productCode(), req.childBatchNo(), now, BatchStatus.QUARANTINED.name(),
                now));
        for (int i = 0; i < items.size(); i++) {
            batchRepo.insertRequiredTest(req.childBatchKey(), items.get(i), i + 1);
        }
        for (int i = 0; i < parentKeys.size(); i++) {
            certRepo.insertMerge(new CertificateRepository.MergeRow(0L, req.childBatchKey(),
                    parentKeys.get(i), i + 1, now));
        }
        for (CertificateRepository.DeclarationRow d : declarations) {
            certRepo.insertBinding(new CertificateRepository.BindingRow(0L,
                    req.childBatchKey(), d.declarationKey(), d.version(), d.materialCode(),
                    d.batchNoPrefix(), actor, now));
        }
        List<MergeResponse.MergeParent> parentBodies = new ArrayList<>(parentKeys.size());
        for (String key : parentKeys) {
            batchRepo.updateStatus(key, BatchStatus.MERGED.name());
            parentBodies.add(new MergeResponse.MergeParent(key,
                    parents.get(key).productCode(), BatchStatus.MERGED));
        }
        MergeResponse body = new MergeResponse(req.childBatchKey(), BatchStatus.QUARANTINED,
                req.productCode(), parentBodies, parentMaterials.size(),
                (int) parentMaterials.stream().filter(covered::contains).count(), 0,
                Instant.parse(now));
        return new StoredResponse(201, toJson(body));
    });
}

/**
 * 放行门禁诊断（只读）：统计当前时点可用于放行的有效绑定声明数，返回实际值、要求值与差额。
 */
public ReleaseCheckResponse releaseCheck(String batchKey) {
    BatchRepository.BatchRow batch = batchRepo.findBatch(batchKey)
            .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
    List<CertificateRepository.DeclarationRow> bound = certRepo.findBoundDeclarations(batchKey);
    Instant nowInstant = clock.instant();
    int valid = 0;
    for (CertificateRepository.DeclarationRow d : bound) {
        if (DeclarationStatus.ACTIVE.name().equals(d.status())
                && d.materialCode().equals(batch.productCode())
                && batch.batchNo().startsWith(d.batchNoPrefix())
                && withinValidity(d, nowInstant)) {
            valid++;
        }
    }
    int missing = Math.max(0, 1 - valid);
    return new ReleaseCheckResponse(batchKey, BatchStatus.valueOf(batch.status()),
            bound.size(), valid, 1, missing, valid >= 1);
}

/**
 * 全部声明版本，按 (declarationKey, version) 稳定排序。
 */
public List<DeclarationVersionResponse> listDeclarations() {
    return certRepo.findAllDeclarations().stream().map(this::toDeclarationResponse).toList();
}

/**
 * 某声明业务键的全部版本明细，按版本号升序。
 */
public List<DeclarationVersionResponse> declarationDetail(String declarationKey) {
    List<CertificateRepository.DeclarationRow> versions = certRepo.findVersions(declarationKey);
    if (versions.isEmpty()) {
        throw ApiException.notFound("声明不存在: " + declarationKey);
    }
    return versions.stream().map(this::toDeclarationResponse).toList();
}

/**
 * 某批次的全部合格证绑定，按绑定顺序稳定排序。
 */
public List<BindingResponse> listBindings(String batchKey) {
    batchRepo.findBatch(batchKey)
            .orElseThrow(() -> ApiException.notFound("批次不存在: " + batchKey));
    return certRepo.findBindings(batchKey).stream().map(this::toBindingResponse).toList();
}

/**
 * 若任一级祖先已被召回则抛 422：后代批次禁止参与合批。
 */
private void assertNoRecalledAncestor(String batchKey) {
    Map<String, String> parentOf = new HashMap<>();
    for (BatchRepository.LineageRow row : batchRepo.findAllLineage()) {
        parentOf.put(row.childKey(), row.parentKey());
    }
    Set<String> recalled = new HashSet<>(batchRepo.findRecalledKeys());
    String current = batchKey;
    while (parentOf.containsKey(current)) {
        current = parentOf.get(current);
        if (recalled.contains(current)) {
            throw ApiException.unprocessable(
                    "祖先批次 " + current + " 已召回，禁止参与合批");
        }
    }
}

