void releaseGate_validityIntervalBoundaries_controllableClock() throws Exception {
    Instant from = Instant.parse("2026-10-01T00:00:00Z");
    Instant to = Instant.parse("2026-11-01T00:00:00Z");
    String decl = "DECL-BND-" + unique();
